from pathlib import Path
from src.config.settings import ENCRYPTED_DIR

def save_encrypted(file_id: str, ciphertext: bytes) -> Path:
    # file_id is generated by the application; reject path separators regardless.
    if not file_id or any(ch not in "0123456789abcdef-" for ch in file_id.lower()):
        raise ValueError("Invalid file ID")
    path = ENCRYPTED_DIR / f"{file_id}.enc"
    path.write_bytes(ciphertext)
    return path

def read_encrypted(file_id: str) -> bytes:
    if not file_id or any(ch not in "0123456789abcdef-" for ch in file_id.lower()):
        raise ValueError("Invalid file ID")
    return (ENCRYPTED_DIR / f"{file_id}.enc").read_bytes()
